import heapq

def match(orders):
    buy_heap = []   # max-heap via negative price: (-price, seq, id)
    sell_heap = []  # min-heap: (price, seq, id)
    seq_counter = 0
    order_info = {}  # id -> dict(side, price, remaining, active)
    trades = []

    for o in orders:
        typ = o[0]

        if typ == 'cancel':
            oid = o[1]
            info = order_info.get(oid)
            if info and info['active']:
                info['active'] = False
            continue

        if typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            _, oid, side, price, qty = o

        remaining = qty
        order_info[oid] = {'side': side, 'price': price, 'remaining': remaining, 'active': True}

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0 and opp_heap:
            top = opp_heap[0]
            if side == 'buy':
                opp_price, opp_seq, opp_id = top
            else:
                neg_price, opp_seq, opp_id = top
                opp_price = -neg_price

            opp_info = order_info.get(opp_id)
            if opp_info is None or not opp_info['active'] or opp_info['remaining'] <= 0:
                heapq.heappop(opp_heap)
                continue

            if typ != 'market':
                if side == 'buy' and price < opp_price:
                    break
                if side == 'sell' and price > opp_price:
                    break

            trade_qty = min(remaining, opp_info['remaining'])
            trade_price = opp_price

            if side == 'buy':
                trades.append([oid, opp_id, trade_price, trade_qty])
            else:
                trades.append([opp_id, oid, trade_price, trade_qty])

            remaining -= trade_qty
            opp_info['remaining'] -= trade_qty

            if opp_info['remaining'] == 0:
                opp_info['active'] = False
                heapq.heappop(opp_heap)

            order_info[oid]['remaining'] = remaining

        order_info[oid]['remaining'] = remaining

        if typ == 'limit' and remaining > 0:
            seq_counter += 1
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq_counter, oid))
            else:
                heapq.heappush(sell_heap, (price, seq_counter, oid))
        else:
            if remaining == 0:
                order_info[oid]['active'] = False
            else:
                # ioc or market with leftover, discard
                order_info[oid]['active'] = False

    return trades

